(()=>{
const themeMeta=document.querySelector('meta[name="theme-color"]');if(themeMeta)themeMeta.content=getComputedStyle(document.documentElement).getPropertyValue('--au-blue').trim();
const header=document.querySelector('.au-header'),toggle=header?.querySelector('.au-menu-toggle'),nav=header?.querySelector('nav');
if(toggle&&nav){
  function closeMenu(restore=false){header.classList.remove('is-menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Открыть меню');if(restore)toggle.focus();}
  toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';header.classList.toggle('is-menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');});
  nav.addEventListener('click',event=>{if(event.target.closest('a'))closeMenu();});
  document.addEventListener('click',event=>{if(!header.contains(event.target))closeMenu();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){event.preventDefault();closeMenu(true);}});
  matchMedia('(max-width:600px)').addEventListener('change',()=>closeMenu());
}
const film=document.querySelector('#au-site .film-section');
if(film){new IntersectionObserver(entries=>film.classList.toggle('is-offscreen',!entries[0].isIntersecting),{threshold:0}).observe(film);document.addEventListener('visibilitychange',()=>film.classList.toggle('is-page-hidden',document.hidden));}
const gallery=document.getElementById('au-gallery-review');
if(gallery){
  const kinds={"zenit":"video","nexemezin":"video","dkkids":"video","dary_2":"video","ovsyasha":"video","ostankino":"video","creamzy":"video","umalat":"video","dary":"video","moskovsky":"video","grand":"video","kumach":"video","worldclass":"graphics","pastrami":"video","gremm":"video","veres":"video","emelya":"video","malysheva":"video","mizura":"graphics","bridgestone":"video","kinomax":"graphics","unionpay":"graphics","novalgin":"video","vico":"video","tikkurila":"graphics","alpen":"graphics","ekzo":"graphics","astellas":"graphics","baikal":"graphics","mense":"graphics","victoria":"video","grand_tea":"video","sheb":"graphics","elkar":"video","tefal":"graphics","papa":"graphics","lacalut":"video","marykay":"video"},links={"zenit":["zenit","project-zenit.html"],"nexemezin":["nexemezin","project-nexemezin.html"],"dkkids":["dkkids","project-dkkids.html"],"dary_2":["case","project-dary_2.html"],"ovsyasha":["ovsyasha","project-ovsyasha.html"],"ostankino":["ostankino","project-ostankino.html"],"creamzy":["creamzy","project-creamzy.html"],"umalat":["umalat","project-umalat.html"],"dary":["dary","project-dary.html"],"moskovsky":["moskovsky","project-moskovsky.html"],"grand":["grand","project-grand.html"],"kumach":["kumach","project-kumach.html"],"worldclass":["worldclass","project-worldclass.html"],"pastrami":["pastrami","project-pastrami.html"],"gremm":["gremm","project-gremm.html"],"veres":["veres","project-veres.html"],"emelya":["emelya","project-emelya.html"],"malysheva":["malysheva","project-malysheva.html"],"mizura":["mizura","project-mizura.html"],"bridgestone":["bridgestone","project-bridgestone.html"],"kinomax":["kinomax","project-kinomax.html"],"unionpay":["unionpay","project-unionpay.html"],"novalgin":["novalgin","project-novalgin.html"],"vico":["vico","project-vico.html"],"tikkurila":["tikkurila","project-tikkurila.html"],"alpen":["alpen","project-alpen.html"],"ekzo":["ekzo","project-ekzo.html"],"astellas":["astellas","project-astellas.html"],"baikal":["baikal","project-baikal.html"],"mense":["mense","project-mense.html"],"victoria":["victoria","project-victoria.html"],"grand_tea":["grand_tea","project-grand_tea.html"],"sheb":["sheb","project-sheb.html"],"elkar":["elkar","project-elkar.html"],"tefal":["tefal","project-tefal.html"],"papa":["papa","project-papa.html"],"lacalut":["lacalut","project-lacalut.html"],"marykay":["marykay","project-marykay.html"]};
  const tiles=[...gallery.querySelectorAll('.au-grid .au-tile')],grid=gallery.querySelector('.au-grid');
  tiles.forEach(tile=>{tile.dataset.kind=kinds[tile.dataset.project]||'graphics';const target=links[tile.dataset.project];if(target&&!tile.querySelector('.au-case-link')){const link=document.createElement('a');link.className='au-case-link';link.dataset.reviewPage=target[0];link.href=''+target[1];link.setAttribute('aria-label','Открыть проект '+tile.querySelector('h2').textContent);tile.append(link);}});
  tiles.forEach(tile=>{const arrow=tile.querySelector('.au-arrow');if(!arrow)return;const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');icon.setAttribute('class','au-arrow-icon');icon.setAttribute('viewBox','0 0 24 24');icon.setAttribute('fill','none');icon.setAttribute('stroke','currentColor');icon.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M5 19 19 5M5 5h14v14');icon.append(path);arrow.setAttribute('aria-hidden','true');arrow.replaceChildren(icon);});
  function setLayout(value){gallery.dataset.mobileLayout=value==='stack'?'stack':'mixed';}
  setLayout(new URLSearchParams(location.search).get('gallery'));
  addEventListener('message',event=>{if(event.source===parent&&event.data?.type==='art-union-gallery-layout')setLayout(event.data.layout);});
  gallery.querySelectorAll('[data-kind-filter]').forEach(button=>button.addEventListener('click',()=>{const kind=button.dataset.kindFilter;tiles.forEach(tile=>tile.hidden=kind!=='all'&&tile.dataset.kind!==kind);grid.classList.toggle('is-filtered',kind!=='all');gallery.querySelectorAll('[data-kind-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
}
})();
